CREATE OR REPLACE FUNCTION bilbbet_private.division_fixture_confirmed(p_round integer,p_home text,p_away text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $function$
 SELECT EXISTS(
 SELECT 1 FROM bilbbet_private.settings s,
 LATERAL jsonb_array_elements(s.value) f
 WHERE s.key='confirmed_division_fixtures'
 AND f->>'section' IN ('ELIZA','DIV2','DIV3')
 AND (f->>'round')::integer=p_round
 AND ((f->>'a'=p_home AND f->>'b'=p_away) OR (f->>'a'=p_away AND f->>'b'=p_home))
 );
$function$;
REVOKE ALL ON FUNCTION bilbbet_private.division_fixture_confirmed(integer,text,text) FROM PUBLIC,anon,authenticated;

